INSERT INTO public.question_bank (id, institution_id, subject_id, topic_id, grade_level_id, class_group_id, question_text, question_type, options, correct_answer, marks, difficulty_level, tags, source, created_by, is_approved, parent_question_id, sub_question_count, sequence_order) VALUES
  ('449cbc4a-b3d9-49e8-85f5-d8ca941942ce', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੈਂ ਕਦੇ ਸੋਚਿਆ ਵੀ ਨਹੀਂ ਸੀ ਕਿ ਇੱਕ ਈਮੇਲ ਮੇਰੀ ਜ਼ਿੰਦਗੀ ਦਾ ਸਭ ਤੋਂ ਸੁਖਦ ਅਨੁਭਵ ਬਣ ਜਾਵੇਗੀ। "ਵਧਾਈ ਹੋਵੇ! ਯੂਨੀਵਰਸਲ ਸਟੇਸ਼ਨਰਜ਼ ਨੇ ਆਪਣੀ BE ਸਾਲਾ ਵਰੇਗੰਢ ਪੂਰੀ ਕਰਨ ਦੀ ਖੁਸ਼ੀ ਵਿੱਚ ਤੁਹਾਨੂੰ ਦੁਬਈ ਦੀ ਮੁਫਤ ਯਾਤਰਾ ਲਈ ਚੁਣਿਆ ਹੈ!" ਇਹ ਪੜ੍ਹ ਕੇ ਮੇਰੇ ਦਿਲ ਦੀ ਧੜਕਣ ਤੇਜ਼ ਹੋ ਗਈ। ਮੈਂ ਮਾਂ ਨੂੰ ਜਦ ਇਹ ਗੱਲ ਦੱਸੀ ਤਾਂ ਉਹਨਾਂ ਨੇ ਕਿਹਾ ਕਿ ਕੋਈ ਮਜ਼ਾਕ ਕਰਦਾ ਹੋਵੇਗਾ। ਜਦ ਕੰਪਨੀ ਦੇ ਨਿੱਜੀ ਨੰਬਰ ਤੋਂ ਫੋਨ ਆਇਆ ਤਾਂ ਇਹ ਸੱਚ ਸਾਡੇ ਸਾਹਮਣੇ ਆਇਆ। ਮੁਫਤ ਟਿਕਟ, ਹੋਟਲ, ਆਵਾਜਾਈ ਦੀ ਸਹੂਲਤ ਸਭ ਕੁਝ ਉਹਨਾਂ ਵੱਲੋਂ ਸੀ। ਭਾਵੇਂ ਮੈਂ ਤਾਂ ਅਜੇ ਪੰਜਾਬ ਤੋਂ ਬਾਹਰ ਨਹੀਂ ਗਿਆ ਸੀ ਪਰ ਦੁਬਈ ਜਾ ਕੇ ਘੁੰਮਣ ਦਾ ਮੇਰਾ ਸੁਫਨਾ ਹਕੀਕਤ ਵਿੱਚ ਬਦਲਣ ਵਾਲਾ ਸੀ। ਇਸ ਅਚਾਨਕ ਆਈ ਖੁਸ਼ੀ ਨੂੰ ਮਹਿਸੂਸ ਕਰਦਿਆਂ ਮੇਰੇ ਤਾਂ ਪੈਰ ਹੀ ਜ਼ਮੀਨ ਉੱਤੇ ਨਹੀਂ ਲੱਗ ਰਹੇ ਸਨ। ਮੈਂ ਮੰਮੀ-ਪਾਪਾ ਨਾਲ ਮਿਲ ਕੇ ਯਾਤਰਾ ਦੀ ਹਰ ਤਰ੍ਹਾਂ ਦੀ ਤਿਆਰੀ ਕਰ ਲਈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('605c0cb0-d9e9-4108-b902-02a1ef05ae06', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਿਰਧਾਰਤ ਸਮੇਂ ਉੱਤੇ ਅਸੀਂ ਦੁਬਈ ਇੰਟਰਨੈਸ਼ਨਲ ਏਅਰਪੋਰਟ ਉੱਤੇ ਉੱਤਰੇ। ਸਾਫ-ਸਫਾਈ, ਚਕਾਚੌਂਧ ਕਰਦੀਆਂ ਲਾਈਟਾਂ ਅਤੇ ਸੁਚਾਰੂ ਪ੍ਰਬੰਧਾਂ ਨੇ ਮੇਰੇ ਮਨ ਉੱਤੇ ਅਮਿੱਟ ਛਾਪ ਛੱਡੀ। ਰੇਤਲਾ ਇਲਾਕਾ ਹੋਣ ਦੇ ਬਾਵਜੂਦ ਦੁਬਈ ਨੂੰ ਸੈਲਾਨੀਆਂ ਲਈ ਖਿੱਚ ਦਾ ਕੇਂਦਰ ਬਣਾਉਣ ਦਾ ਸਿਹਰਾ ਸਮੇਂ-ਸਮੇਂ ਉੱਤੇ ਇਸ ਦੇਸ਼ ਨੂੰ ਚਲਾਉਣ ਵਾਲਿਆਂ ਦੇ ਸਿਰ ਬੱਝਦਾ ਹੈ। ਇੱਥੋਂ ਦੀਆਂ ਬਹੁਮੰਜ਼ਲੀ ਇਮਾਰਤਾਂ, ਮਿਊਜ਼ੀਅਮ ਅਤੇ ਰੇਤ ਦੇ ਉੱਚੇ-ਉੱਚੇ ਟਿੱਬੇ ਇਸ ਨੂੰ ਖੂਬਸੂਰਤ ਦਿੱਖ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਨ। ਇੱਥੇ ਬਣੀ ਦੁਨੀਆ ਦੀ ਸਭ ਤੋਂ ਵਿਲੱਖਣ ਇਮਾਰਤ ਬੁਰਜ ਖਲੀਫਾ ਸਭ ਦਾ ਧਿਆਨ ਖਿੱਚਦੀ ਹੈ। ਇਸ ਅਜੂਬੇ ਨੂੰ ਵੇਖਣ ਲਈ ਮੈਂ ਵੀ ਬੜਾ ਉਤਾਵਲਾ ਸੀ। ਜਦੋਂ ਮੈਂ ਇਸ ਇਮਾਰਤ ਨੂੰ ਪਹਿਲੀ ਵਾਰ ਵੇਖਿਆ ਤਾਂ ਵੇਖਦਾ ਹੀ ਰਹਿ ਗਿਆ। ਹਜ਼ਾਰਾਂ ਲੋਕ ਇਹ ਨਜ਼ਾਰਾ ਸਾਹ ਰੋਕ ਕੇ ਵੇਖ ਰਹੇ ਸਨ। ਇਹ ਅਸਮਾਨ ਵਿੱਚ ਮੁੱਖ ਵਿਚਾਰ (Key Concept) ਆਧੁਨਿਕ ਤਕਨੀਕ ਦੀਆਂ ਨਵੀਆਂ ਪ੍ਰਾਪਤੀਆਂ ਤੋਂ ਜਾਣੂ ਕਰਾਉਂਦਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
