  ('a26eb935-84f4-48f1-83de-a3452eaea4dc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਿਰਧਾਰਤ ਸਮੇਂ ਉੱਤੇ ਅਸੀਂ ਦੁਬਈ ਇੰਟਰਨੈਸ਼ਨਲ ਏਅਰਪੋਰਟ ਉੱਤੇ ਉੱਤਰੇ। ਸਾਫ-ਸਫਾਈ, ਚਕਾਚੌਂਧ ਕਰਦੀਆਂ ਲਾਈਟਾਂ ਅਤੇ ਸੁਚਾਰੂ ਪ੍ਰਬੰਧਾਂ ਨੇ ਮੇਰੇ ਮਨ ਉੱਤੇ ਅਮਿੱਟ ਛਾਪ ਛੱਡੀ। ਰੇਤਲਾ ਇਲਾਕਾ ਹੋਣ ਦੇ ਬਾਵਜੂਦ ਦੁਬਈ ਨੂੰ ਸੈਲਾਨੀਆਂ ਲਈ ਖਿੱਚ ਦਾ ਕੇਂਦਰ ਬਣਾਉਣ ਦਾ ਸਿਹਰਾ ਸਮੇਂ-ਸਮੇਂ ਉੱਤੇ ਇਸ ਦੇਸ਼ ਨੂੰ ਚਲਾਉਣ ਵਾਲਿਆਂ ਦੇ ਸਿਰ ਬੱਝਦਾ ਹੈ। ਇੱਥੋਂ ਦੀਆਂ ਬਹੁਮੰਜ਼ਲੀ ਇਮਾਰਤਾਂ, ਮਿਊਜ਼ੀਅਮ ਅਤੇ ਰੇਤ ਦੇ ਉੱਚੇ-ਉੱਚੇ ਟਿੱਬੇ ਇਸ ਨੂੰ ਖੂਬਸੂਰਤ ਦਿੱਖ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਨ। ਇੱਥੇ ਬਣੀ ਦੁਨੀਆ ਦੀ ਸਭ ਤੋਂ ਵਿਲੱਖਣ ਇਮਾਰਤ ਬੁਰਜ ਖਲੀਫਾ ਸਭ ਦਾ ਧਿਆਨ ਖਿੱਚਦੀ ਹੈ। ਇਸ ਅਜੂਬੇ ਨੂੰ ਵੇਖਣ ਲਈ ਮੈਂ ਵੀ ਬੜਾ ਉਤਾਵਲਾ ਸੀ। ਜਦੋਂ ਮੈਂ ਇਸ ਇਮਾਰਤ ਨੂੰ ਪਹਿਲੀ ਵਾਰ ਵੇਖਿਆ ਤਾਂ ਵੇਖਦਾ ਹੀ ਰਹਿ ਗਿਆ। ਹਜ਼ਾਰਾਂ ਲੋਕ ਇਹ ਨਜ਼ਾਰਾ ਸਾਹ ਰੋਕ ਕੇ ਵੇਖ ਰਹੇ ਸਨ। ਇਹ ਅਸਮਾਨ ਵਿੱਚ ਮੁੱਖ ਵਿਚਾਰ (Key Concept) ਆਧੁਨਿਕ ਤਕਨੀਕ ਦੀਆਂ ਨਵੀਆਂ ਪ੍ਰਾਪਤੀਆਂ ਤੋਂ ਜਾਣੂ ਕਰਾਉਂਦਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('43f38738-2f53-4146-b439-b0173d76bb1c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੈਂ ਕਦੇ ਸੋਚਿਆ ਵੀ ਨਹੀਂ ਸੀ ਕਿ ਇੱਕ ਈਮੇਲ ਮੇਰੀ ਜ਼ਿੰਦਗੀ ਦਾ ਸਭ ਤੋਂ ਸੁਖਦ ਅਨੁਭਵ ਬਣ ਜਾਵੇਗੀ। "ਵਧਾਈ ਹੋਵੇ! ਯੂਨੀਵਰਸਲ ਸਟੇਸ਼ਨਰਜ਼ ਨੇ ਆਪਣੀ BE ਸਾਲਾ ਵਰੇਗੰਢ ਪੂਰੀ ਕਰਨ ਦੀ ਖੁਸ਼ੀ ਵਿੱਚ ਤੁਹਾਨੂੰ ਦੁਬਈ ਦੀ ਮੁਫਤ ਯਾਤਰਾ ਲਈ ਚੁਣਿਆ ਹੈ!" ਇਹ ਪੜ੍ਹ ਕੇ ਮੇਰੇ ਦਿਲ ਦੀ ਧੜਕਣ ਤੇਜ਼ ਹੋ ਗਈ। ਮੈਂ ਮਾਂ ਨੂੰ ਜਦ ਇਹ ਗੱਲ ਦੱਸੀ ਤਾਂ ਉਹਨਾਂ ਨੇ ਕਿਹਾ ਕਿ ਕੋਈ ਮਜ਼ਾਕ ਕਰਦਾ ਹੋਵੇਗਾ। ਜਦ ਕੰਪਨੀ ਦੇ ਨਿੱਜੀ ਨੰਬਰ ਤੋਂ ਫੋਨ ਆਇਆ ਤਾਂ ਇਹ ਸੱਚ ਸਾਡੇ ਸਾਹਮਣੇ ਆਇਆ। ਮੁਫਤ ਟਿਕਟ, ਹੋਟਲ, ਆਵਾਜਾਈ ਦੀ ਸਹੂਲਤ ਸਭ ਕੁਝ ਉਹਨਾਂ ਵੱਲੋਂ ਸੀ। ਭਾਵੇਂ ਮੈਂ ਤਾਂ ਅਜੇ ਪੰਜਾਬ ਤੋਂ ਬਾਹਰ ਨਹੀਂ ਗਿਆ ਸੀ ਪਰ ਦੁਬਈ ਜਾ ਕੇ ਘੁੰਮਣ ਦਾ ਮੇਰਾ ਸੁਫਨਾ ਹਕੀਕਤ ਵਿੱਚ ਬਦਲਣ ਵਾਲਾ ਸੀ। ਇਸ ਅਚਾਨਕ ਆਈ ਖੁਸ਼ੀ ਨੂੰ ਮਹਿਸੂਸ ਕਰਦਿਆਂ ਮੇਰੇ ਤਾਂ ਪੈਰ ਹੀ ਜ਼ਮੀਨ ਉੱਤੇ ਨਹੀਂ ਲੱਗ ਰਹੇ ਸਨ। ਮੈਂ ਮੰਮੀ-ਪਾਪਾ ਨਾਲ ਮਿਲ ਕੇ ਯਾਤਰਾ ਦੀ ਹਰ ਤਰ੍ਹਾਂ ਦੀ ਤਿਆਰੀ ਕਰ ਲਈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('fea3795e-9d97-441d-b688-1d5cfba9d4dd', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਿਰਧਾਰਤ ਸਮੇਂ ਉੱਤੇ ਅਸੀਂ ਦੁਬਈ ਇੰਟਰਨੈਸ਼ਨਲ ਏਅਰਪੋਰਟ ਉੱਤੇ ਉੱਤਰੇ। ਸਾਫ-ਸਫਾਈ, ਚਕਾਚੌਂਧ ਕਰਦੀਆਂ ਲਾਈਟਾਂ ਅਤੇ ਸੁਚਾਰੂ ਪ੍ਰਬੰਧਾਂ ਨੇ ਮੇਰੇ ਮਨ ਉੱਤੇ ਅਮਿੱਟ ਛਾਪ ਛੱਡੀ। ਰੇਤਲਾ ਇਲਾਕਾ ਹੋਣ ਦੇ ਬਾਵਜੂਦ ਦੁਬਈ ਨੂੰ ਸੈਲਾਨੀਆਂ ਲਈ ਖਿੱਚ ਦਾ ਕੇਂਦਰ ਬਣਾਉਣ ਦਾ ਸਿਹਰਾ ਸਮੇਂ-ਸਮੇਂ ਉੱਤੇ ਇਸ ਦੇਸ਼ ਨੂੰ ਚਲਾਉਣ ਵਾਲਿਆਂ ਦੇ ਸਿਰ ਬੱਝਦਾ ਹੈ। ਇੱਥੋਂ ਦੀਆਂ ਬਹੁਮੰਜ਼ਲੀ ਇਮਾਰਤਾਂ, ਮਿਊਜ਼ੀਅਮ ਅਤੇ ਰੇਤ ਦੇ ਉੱਚੇ-ਉੱਚੇ ਟਿੱਬੇ ਇਸ ਨੂੰ ਖੂਬਸੂਰਤ ਦਿੱਖ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਨ। ਇੱਥੇ ਬਣੀ ਦੁਨੀਆ ਦੀ ਸਭ ਤੋਂ ਵਿਲੱਖਣ ਇਮਾਰਤ ਬੁਰਜ ਖਲੀਫਾ ਸਭ ਦਾ ਧਿਆਨ ਖਿੱਚਦੀ ਹੈ। ਇਸ ਅਜੂਬੇ ਨੂੰ ਵੇਖਣ ਲਈ ਮੈਂ ਵੀ ਬੜਾ ਉਤਾਵਲਾ ਸੀ। ਜਦੋਂ ਮੈਂ ਇਸ ਇਮਾਰਤ ਨੂੰ ਪਹਿਲੀ ਵਾਰ ਵੇਖਿਆ ਤਾਂ ਵੇਖਦਾ ਹੀ ਰਹਿ ਗਿਆ। ਹਜ਼ਾਰਾਂ ਲੋਕ ਇਹ ਨਜ਼ਾਰਾ ਸਾਹ ਰੋਕ ਕੇ ਵੇਖ ਰਹੇ ਸਨ। ਇਹ ਅਸਮਾਨ ਵਿੱਚ ਮੁੱਖ ਵਿਚਾਰ (Key Concept) ਆਧੁਨਿਕ ਤਕਨੀਕ ਦੀਆਂ ਨਵੀਆਂ ਪ੍ਰਾਪਤੀਆਂ ਤੋਂ ਜਾਣੂ ਕਰਾਉਂਦਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('5f0309a6-fbfa-43d0-855e-21227829655f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਧੀ ਖੜ੍ਹੀ ਹੋਈ ਜਾਦੂਈ ਮੂਰਤ ਵਾਂਗ ਜਾਪਦੀ ਹੈ। HBH ਮੀਟਰ ਉੱਚੀ ਇਹ ਇਮਾਰਤ ਮਨੁੱਖੀ ਕਲਪਨਾ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ ਕਲਾ ਦਾ ਅਦਭੁਤ ਨਮੂਨਾ ਹੈ। ਬੁਰਜ ਖਲੀਫਾ ਦਾ ਨਿਰਮਾਣ B@@D ਵਿੱਚ ਸ਼ੁਰੂ ਹੋਇਆ ਸੀ ਤੇ ਇਹ B@A@ ਵਿੱਚ ਪੂਰੀ ਤਰ੍ਹਾਂ ਤਿਆਰ ਹੋ ਗਈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a9f128b9-afc1-484e-a4ba-a77a12bd0feb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਇਮਾਰਤ ਨੇ ਸੰਸਾਰ ਦੀ ਸਭ ਤੋਂ ਉੱਚੀ ਇਮਾਰਤ ਬਣਨ ਦਾ ਰਿਕਾਰਡ ਦਰਜ ਕਰਵਾਇਆ ਹੈ। ਇਸ ਇਮਾਰਤ ਦੀਆਂ AFC ਮੁੱਖ ਮੰਜ਼ਿਲਾਂ ਹਨ ਪਰ ਕੁੱਲ ਮਿਲਾ ਕੇ ਇਹ ਲਗਭਗ B@@ ਤਲਾਂ ਉੱਤੇ ਫੈਲੀ ਹੋਈ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('aa2e5c8d-8217-4ed7-8aa6-f2a170e61f01', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਪ੍ਰਾਜੈਕਟ ਸੰਯੁਕਤ ਅਰਬ ਅਮੀਰਾਤ ਦੀ ਇੱਕ ਪ੍ਰਸਿੱਧ ਰੀਅਲ ਅਸਟੇਟ ਕੰਪਨੀ ਐਮਾਰ ਪ੍ਰਾਪਰਟੀਜ਼ ਵੱਲੋਂ ਆਰੰਭ ਕੀਤਾ ਗਿਆ ਸੀ। ਇਸ ਇਮਾਰਤ ਦਾ ਨਮੂਨਾ ਸਕਿਡਮੋਰ, ਓਵਿੰਗਸ ਐਂਡ ਮੈਰਿਲ (Skidmore, Owings & Merrill) (SOM) ਨਾਮਕ ਅਮਰੀਕੀ ਆਰਕੀਟੈਕਚਰ ਕੰਪਨੀ ਨੇ ਤਿਆਰ ਕੀਤਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4ce3ba62-f582-49dc-9201-3a5eceea4d8d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੁੱਖ ਆਰਕੀਟੈਕਟ ਐਡਰਿਅਨ ਸਮਿੱਥ ਸੀ ਜਿਸ ਨੇ ਲਿੱਲੀ ਫੁੱਲ (Hymenocallis) ਦੀ ਬਣਤਰ ਤੋਂ ਪ੍ਰੇਰਿਤ ਹੋ ਕੇ ਇਹ ਅਸਾਧਾਰਨ ਡਿਜ਼ਾਈਨ ਤਿਆਰ ਕੀਤਾ। ਇਸ ਦੀ ਬਣਤਰ ਤਕਨੀਕੀ ਅਨੋਖੇਪਨ ਨਾਲ ਭਰੀ ਹੋਈ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9ea80e5a-53d7-4da0-8fd4-0334ffdab8bc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਦਾ ਆਧਾਰ ਤਿਕੋਣੀ ਆਕਾਰ ਦਾ ਹੈ ਜੋ ਇੱਕ ਕੇਂਦਰੀ ਕੋਰ ਵਿੱਚੋਂ ਤਿੰਨ ਦਿਸ਼ਾਵਾਂ ਵਿੱਚ ਫੈਲਦਾ ਹੈ। ਇਹ ਨਕਸ਼ਾ ਨਾ ਸਿਰਫ਼ ਸੁੰਦਰਤਾ ਵਿੱਚ ਵਾਧਾ ਕਰਦਾ ਹੈ, ਸਗੋਂ ਇਸੇ ਤਿਕੋਣੇ ਨਮੂਨੇ ਕਰਕੇ ਹੀ ਇਹ EE ਤੋਂ F@ ਕਿਲੋਮੀਟਰ ਤੇਜ਼ ਹਵਾਵਾਂ ਦੇ ਜ਼ੋਰਦਾਰ ਝਟਕਿਆਂ ਨੂੰ ਵੀ ਆਸਾਨੀ ਨਾਲ ਸਹਿਣ ਕਰ ਲੈਂਦੀ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b3940138-f312-4105-ae28-379bfa292da7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਉੱਚਾਈ ਉੱਤੇ ਹਵਾ ਦਾ ਜ਼ੋਰ ਜ਼ਿਆਦਾ ਹੋਣ ਕਰਕੇ ਇਹ ਆਮ ਗੱਲ ਨਹੀਂ ਹੈ। ਇਸ ਦਾ ਵਿਸ਼ੇਸ਼ ਨਮੂਨਾ ਹਵਾ ਦੇ ਪ੍ਰਵਾਹ ਨੂੰ ਇਸ ਤਰ੍ਹਾਂ ਮੋੜਦਾ ਹੈ ਕਿ ਇਮਾਰਤ ਥਰਥਰਾਉਣ ਤੋਂ ਬਚ ਕੇ ਸ਼ਾਂਤ ਖੜ੍ਹੀ ਰਹਿੰਦੀ ਹੈ। ਇਸੇ ਡਿਜ਼ਾਈਨ ਇਸ ਦੀ ਸਥਿਰਤਾ ਦੀ ਬੁਨਿਆਦ ਬਣਦਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fc50009e-18c5-40b9-91f9-b15244676a75', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਦੇ ਬਾਹਰੀ ਹਿੱਸਿਆਂ ਉੱਤੇ ਲਗਾਏ ਗਏ ਵਿਸ਼ੇਸ਼ ਗਲਾਸ ਪੈਨਲਾਂ ਨੂੰ ਐਨੀ ਅਗਾਹਵਧੂ ਤਕਨੀਕ ਨਾਲ ਤਿਆਰ ਕੀਤਾ ਗਿਆ ਹੈ ਕਿ ਇਹ ਸੂਰਜ ਦੀ ਉਤਪੰਨ ਕੀਤੀ ਗਰਮੀ ਨੂੰ ਘਟਾਉਂਦੇ ਹਨ ਜਿਸ ਨਾਲ ਇਮਾਰਤ ਦੇ ਅੰਦਰ ਸ਼ੀਤਲਤਾ ਬਣੀ ਰਹਿੰਦੀ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('caa17e25-0926-4c76-8486-4be2ff66cfd0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਟਿਕਾਊ ਬਣਤਰ ਅਤੇ ਕਾਫ਼ੀ ਘੱਟ ਊਰਜਾ ਖਪਤ ਕਰਨ ਵਾਲੀ ਇਹ ਸੰਰਚਨਾ ਭਵਿੱਖ ਦੀਆਂ ਇਮਾਰਤਾਂ ਲਈ ਪ੍ਰੇਰਨਾ ਹੈ। ਬੁਰਜ ਖਲੀਫਾ ਸਿਰਫ਼ ਬਹੁਮੰਜ਼ਲੀ ਇਮਾਰਤ ਨਹੀਂ, ਸਗੋਂ ਜ਼ਿੰਦਗੀ ਜਿਊਣ ਵਾਲੀ ਥਾਂ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d100c5de-7d08-4969-b356-cedd5832b09c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੱਥੇ ਰਿਹਾਇਸ਼ੀ ਅਪਾਰਟਮੈਂਟ, ਦਫ਼ਤਰ, ਹੋਟਲ ਅਤੇ ਵਪਾਰਕ ਸਥਾਨ ਵੀ ਹਨ। ਇਮਾਰਤ ਦੇ ਨੀਵੇਂ ਤਲਾਂ ਉੱਤੇ ਅਰਮਾਨੀ ਹੋਟਲ ਦੁਬਈ ਸਥਿਤ ਹੈ ਜੋ ਇਟਲੀ ਦੇ ਮਸ਼ਹੂਰ ਡਿਜ਼ਾਈਨਰ ਜਾਰਜੀਓ ਅਰਮਾਨੀ ਦੇ ਨਾਂ ਉੱਤੇ ਬਣਾਇਆ ਗਿਆ ਇੱਕ ਵਿਲੱਖਣ ਹੋਟਲ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9bceb98d-865d-4720-9406-bde618db2565', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਧੀ ਖੜ੍ਹੀ ਹੋਈ ਜਾਦੂਈ ਮੂਰਤ ਵਾਂਗ ਜਾਪਦੀ ਹੈ। HBH ਮੀਟਰ ਉੱਚੀ ਇਹ ਇਮਾਰਤ ਮਨੁੱਖੀ ਕਲਪਨਾ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ ਕਲਾ ਦਾ ਅਦਭੁਤ ਨਮੂਨਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8ba97ad6-3dc0-430b-9291-943c3b286027', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬੁਰਜ ਖਲੀਫਾ ਦਾ ਨਿਰਮਾਣ B@@D ਵਿੱਚ ਸ਼ੁਰੂ ਹੋਇਆ ਸੀ ਤੇ ਇਹ B@A@ ਵਿੱਚ ਪੂਰੀ ਤਰ੍ਹਾਂ ਤਿਆਰ ਹੋ ਗਈ। ਇਸ ਇਮਾਰਤ ਨੇ ਸੰਸਾਰ ਦੀ ਸਭ ਤੋਂ ਉੱਚੀ ਇਮਾਰਤ ਬਣਨ ਦਾ ਰਿਕਾਰਡ ਦਰਜ ਕਰਵਾਇਆ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
