  ('c833692d-bc08-4c2a-9056-e52f461e9fa6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਇਮਾਰਤ ਦਾ ਨਮੂਨਾ ਸਕਿਡਮੋਰ, ਓਵਿੰਗਸ ਐਂਡ ਮੈਰਿਲ (Skidmore, Owings & Merrill) (SOM) ਨਾਮਕ ਅਮਰੀਕੀ ਆਰਕੀਟੈਕਚਰ ਕੰਪਨੀ ਨੇ ਤਿਆਰ ਕੀਤਾ। ਮੁੱਖ ਆਰਕੀਟੈਕਟ ਐਡਰਿਅਨ ਸਮਿੱਥ ਸੀ ਜਿਸ ਨੇ ਲਿੱਲੀ ਫੁੱਲ (Hymenocallis) ਦੀ ਬਣਤਰ ਤੋਂ ਪ੍ਰੇਰਿਤ ਹੋ ਕੇ ਇਹ ਅਸਾਧਾਰਨ ਡਿਜ਼ਾਈਨ ਤਿਆਰ ਕੀਤਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
