  ('146e65c1-72a4-416c-98e3-1d010f4c08da', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸੇ ਡਿਜ਼ਾਈਨ ਇਸ ਦੀ ਸਥਿਰਤਾ ਦੀ ਬੁਨਿਆਦ ਬਣਦਾ ਹੈ। ਇਸ ਦੇ ਬਾਹਰੀ ਹਿੱਸਿਆਂ ਉੱਤੇ ਲਗਾਏ ਗਏ ਵਿਸ਼ੇਸ਼ ਗਲਾਸ ਪੈਨਲਾਂ ਨੂੰ ਐਨੀ ਅਗਾਹਵਧੂ ਤਕਨੀਕ ਨਾਲ ਤਿਆਰ ਕੀਤਾ ਗਿਆ ਹੈ ਕਿ ਇਹ ਸੂਰਜ ਦੀ ਉਤਪੰਨ ਕੀਤੀ ਗਰਮੀ ਨੂੰ ਘਟਾਉਂਦੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b8678a03-d2f4-4ff4-9086-bd29d20de9d4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜਿਸ ਨਾਲ ਇਮਾਰਤ ਦੇ ਅੰਦਰ ਸ਼ੀਤਲਤਾ ਬਣੀ ਰਹਿੰਦੀ ਹੈ। ਟਿਕਾਊ ਬਣਤਰ ਅਤੇ ਕਾਫ਼ੀ ਘੱਟ ਊਰਜਾ ਖਪਤ ਕਰਨ ਵਾਲੀ ਇਹ ਸੰਰਚਨਾ ਭਵਿੱਖ ਦੀਆਂ ਇਮਾਰਤਾਂ ਲਈ ਪ੍ਰੇਰਨਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('97e3afa4-cbc3-4d54-8c48-fc392a576bd4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬੁਰਜ ਖਲੀਫਾ ਸਿਰਫ਼ ਬਹੁਮੰਜ਼ਲੀ ਇਮਾਰਤ ਨਹੀਂ, ਸਗੋਂ ਜ਼ਿੰਦਗੀ ਜਿਊਣ ਵਾਲੀ ਥਾਂ ਹੈ। ਇੱਥੇ ਰਿਹਾਇਸ਼ੀ ਅਪਾਰਟਮੈਂਟ, ਦਫ਼ਤਰ, ਹੋਟਲ ਅਤੇ ਵਪਾਰਕ ਸਥਾਨ ਵੀ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2d6c349f-7132-4312-96bc-5b076ad9b641', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਮਾਰਤ ਦੇ ਨੀਵੇਂ ਤਲਾਂ ਉੱਤੇ ਅਰਮਾਨੀ ਹੋਟਲ ਦੁਬਈ ਸਥਿਤ ਹੈ ਜੋ ਇਟਲੀ ਦੇ ਮਸ਼ਹੂਰ ਡਿਜ਼ਾਈਨਰ ਜਾਰਜੀਓ ਅਰਮਾਨੀ ਦੇ ਨਾਂ ਉੱਤੇ ਬਣਾਇਆ ਗਿਆ ਇੱਕ ਵਿਲੱਖਣ ਹੋਟਲ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('90b854d1-8402-4c96-9a79-65d7e006029e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪ੍ਰੇਰਿਤ - ਪ੍ਰੇਰਨਾ ਦੇਣ ਵਾਲੀ ਚੀਜ਼ (source of inspiration), ਅਸਾਧਾਰਨ - ਬਹੁਤ ਵੱਖਰਾ (extraordinary), ਥਰਥਰਾਉਣਾ - ਕੰਬਣਾ (vibration/shaking), ਟਿਕਾਊ - ਮਜ਼ਬੂਤ ਤੇ ਲੰਮਾ ਚੱਲਣ ਵਾਲਾ (durable)。$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ba7ca96a-1007-41f2-80cb-87383c199b2b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਧੀ ਖੜ੍ਹੀ ਹੋਈ ਜਾਦੂਈ ਮੂਰਤ ਵਾਂਗ ਜਾਪਦੀ ਹੈ। HBH ਮੀਟਰ ਉੱਚੀ ਇਹ ਇਮਾਰਤ ਮਨੁੱਖੀ ਕਲਪਨਾ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ ਕਲਾ ਦਾ ਅਦਭੁਤ ਨਮੂਨਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f7439601-965f-4955-8e59-2921be7be7b6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਇਮਾਰਤ ਨੇ ਸੰਸਾਰ ਦੀ ਸਭ ਤੋਂ ਉੱਚੀ ਇਮਾਰਤ ਬਣਨ ਦਾ ਰਿਕਾਰਡ ਦਰਜ ਕਰਵਾਇਆ ਹੈ। ਇਸ ਇਮਾਰਤ ਦੀਆਂ AFC ਮੁੱਖ ਮੰਜ਼ਿਲਾਂ ਹਨ ਪਰ ਕੁੱਲ ਮਿਲਾ ਕੇ ਇਹ ਲਗਭਗ B@@ ਤਲਾਂ ਉੱਤੇ ਫੈਲੀ ਹੋਈ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('de9bfa14-3dbe-46a8-8758-e9ab99989a37', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਦਾ ਵਿਸ਼ੇਸ਼ ਨਮੂਨਾ ਹਵਾ ਦੇ ਪ੍ਰਵਾਹ ਨੂੰ ਇਸ ਤਰ੍ਹਾਂ ਮੋੜਦਾ ਹੈ ਕਿ ਇਮਾਰਤ ਥਰਥਰਾਉਣ ਤੋਂ ਬਚ ਕੇ ਸ਼ਾਂਤ ਖੜ੍ਹੀ ਰਹਿੰਦੀ ਹੈ। ਇਸੇ ਡਿਜ਼ਾਈਨ ਇਸ ਦੀ ਸਥਿਰਤਾ ਦੀ ਬੁਨਿਆਦ ਬਣਦਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('847513c1-b2f8-4613-9593-0ed493e170ca', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੈਂ ਕਦੇ ਸੋਚਿਆ ਵੀ ਨਹੀਂ ਸੀ ਕਿ ਇੱਕ ਈਮੇਲ ਮੇਰੀ ਜ਼ਿੰਦਗੀ ਦਾ ਸਭ ਤੋਂ ਸੁਖਦ ਅਨੁਭਵ ਬਣ ਜਾਵੇਗੀ। "ਵਧਾਈ ਹੋਵੇ! ਯੂਨੀਵਰਸਲ ਸਟੇਸ਼ਨਰਜ਼ ਨੇ ਆਪਣੀ BE ਸਾਲਾ ਵਰੇਗੰਢ ਪੂਰੀ ਕਰਨ ਦੀ ਖੁਸ਼ੀ ਵਿੱਚ ਤੁਹਾਨੂੰ ਦੁਬਈ ਦੀ ਮੁਫਤ ਯਾਤਰਾ ਲਈ ਚੁਣਿਆ ਹੈ!" ਇਹ ਪੜ੍ਹ ਕੇ ਮੇਰੇ ਦਿਲ ਦੀ ਧੜਕਣ ਤੇਜ਼ ਹੋ ਗਈ। ਮੈਂ ਮਾਂ ਨੂੰ ਜਦ ਇਹ ਗੱਲ ਦੱਸੀ ਤਾਂ ਉਹਨਾਂ ਨੇ ਕਿਹਾ ਕਿ ਕੋਈ ਮਜ਼ਾਕ ਕਰਦਾ ਹੋਵੇਗਾ। ਜਦ ਕੰਪਨੀ ਦੇ ਨਿੱਜੀ ਨੰਬਰ ਤੋਂ ਫੋਨ ਆਇਆ ਤਾਂ ਇਹ ਸੱਚ ਸਾਡੇ ਸਾਹਮਣੇ ਆਇਆ। ਮੁਫਤ ਟਿਕਟ, ਹੋਟਲ, ਆਵਾਜਾਈ ਦੀ ਸਹੂਲਤ ਸਭ ਕੁਝ ਉਹਨਾਂ ਵੱਲੋਂ ਸੀ। ਭਾਵੇਂ ਮੈਂ ਤਾਂ ਅਜੇ ਪੰਜਾਬ ਤੋਂ ਬਾਹਰ ਨਹੀਂ ਗਿਆ ਸੀ ਪਰ ਦੁਬਈ ਜਾ ਕੇ ਘੁੰਮਣ ਦਾ ਮੇਰਾ ਸੁਫਨਾ ਹਕੀਕਤ ਵਿੱਚ ਬਦਲਣ ਵਾਲਾ ਸੀ। ਇਸ ਅਚਾਨਕ ਆਈ ਖੁਸ਼ੀ ਨੂੰ ਮਹਿਸੂਸ ਕਰਦਿਆਂ ਮੇਰੇ ਤਾਂ ਪੈਰ ਹੀ ਜ਼ਮੀਨ ਉੱਤੇ ਨਹੀਂ ਲੱਗ ਰਹੇ ਸਨ। ਮੈਂ ਮੰਮੀ-ਪਾਪਾ ਨਾਲ ਮਿਲ ਕੇ ਯਾਤਰਾ ਦੀ ਹਰ ਤਰ੍ਹਾਂ ਦੀ ਤਿਆਰੀ ਕਰ ਲਈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
  ('c376760e-b615-430e-b775-4bb2c75cb13d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਿਰਧਾਰਤ ਸਮੇਂ ਉੱਤੇ ਅਸੀਂ ਦੁਬਈ ਇੰਟਰਨੈਸ਼ਨਲ ਏਅਰਪੋਰਟ ਉੱਤੇ ਉੱਤਰੇ। ਸਾਫ-ਸਫਾਈ, ਚਕਾਚੌਂਧ ਕਰਦੀਆਂ ਲਾਈਟਾਂ ਅਤੇ ਸੁਚਾਰੂ ਪ੍ਰਬੰਧਾਂ ਨੇ ਮੇਰੇ ਮਨ ਉੱਤੇ ਅਮਿੱਟ ਛਾਪ ਛੱਡੀ। ਰੇਤਲਾ ਇਲਾਕਾ ਹੋਣ ਦੇ ਬਾਵਜੂਦ ਦੁਬਈ ਨੂੰ ਸੈਲਾਨੀਆਂ ਲਈ ਖਿੱਚ ਦਾ ਕੇਂਦਰ ਬਣਾਉਣ ਦਾ ਸਿਹਰਾ ਸਮੇਂ-ਸਮੇਂ ਉੱਤੇ ਇਸ ਦੇਸ਼ ਨੂੰ ਚਲਾਉਣ ਵਾਲਿਆਂ ਦੇ ਸਿਰ ਬੱਝਦਾ ਹੈ। ਇੱਥੋਂ ਦੀਆਂ ਬਹੁਮੰਜ਼ਲੀ ਇਮਾਰਤਾਂ, ਮਿਊਜ਼ੀਅਮ ਅਤੇ ਰੇਤ ਦੇ ਉੱਚੇ-ਉੱਚੇ ਟਿੱਬੇ ਇਸ ਨੂੰ ਖੂਬਸੂਰਤ ਦਿੱਖ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਨ। ਇੱਥੇ ਬਣੀ ਦੁਨੀਆ ਦੀ ਸਭ ਤੋਂ ਵਿਲੱਖਣ ਇਮਾਰਤ ਬੁਰਜ ਖਲੀਫਾ ਸਭ ਦਾ ਧਿਆਨ ਖਿੱਚਦੀ ਹੈ। ਇਸ ਅਜੂਬੇ ਨੂੰ ਵੇਖਣ ਲਈ ਮੈਂ ਵੀ ਬੜਾ ਉਤਾਵਲਾ ਸੀ। ਜਦੋਂ ਮੈਂ ਇਸ ਇਮਾਰਤ ਨੂੰ ਪਹਿਲੀ ਵਾਰ ਵੇਖਿਆ ਤਾਂ ਵੇਖਦਾ ਹੀ ਰਹਿ ਗਿਆ। ਹਜ਼ਾਰਾਂ ਲੋਕ ਇਹ ਨਜ਼ਾਰਾ ਸਾਹ ਰੋਕ ਕੇ ਵੇਖ ਰਹੇ ਸਨ। ਇਹ ਅਸਮਾਨ ਵਿੱਚ ਮੁੱਖ ਵਿਚਾਰ (Key Concept) ਆਧੁਨਿਕ ਤਕਨੀਕ ਦੀਆਂ ਨਵੀਆਂ ਪ੍ਰਾਪਤੀਆਂ ਤੋਂ ਜਾਣੂ ਕਰਾਉਂਦਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
