  ('a11d50ff-664f-4d8d-9a43-76c4b166d11d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਿਰਧਾਰਤ ਸਮੇਂ ਉੱਤੇ ਅਸੀਂ ਦੁਬਈ ਇੰਟਰਨੈਸ਼ਨਲ ਏਅਰਪੋਰਟ ਉੱਤੇ ਉੱਤਰੇ। ਸਾਫ-ਸਫਾਈ, ਚਕਾਚੌਂਧ ਕਰਦੀਆਂ ਲਾਈਟਾਂ ਅਤੇ ਸੁਚਾਰੂ ਪ੍ਰਬੰਧਾਂ ਨੇ ਮੇਰੇ ਮਨ ਉੱਤੇ ਅਮਿੱਟ ਛਾਪ ਛੱਡੀ। ਰੇਤਲਾ ਇਲਾਕਾ ਹੋਣ ਦੇ ਬਾਵਜੂਦ ਦੁਬਈ ਨੂੰ ਸੈਲਾਨੀਆਂ ਲਈ ਖਿੱਚ ਦਾ ਕੇਂਦਰ ਬਣਾਉਣ ਦਾ ਸਿਹਰਾ ਸਮੇਂ-ਸਮੇਂ ਉੱਤੇ ਇਸ ਦੇਸ਼ ਨੂੰ ਚਲਾਉਣ ਵਾਲਿਆਂ ਦੇ ਸਿਰ ਬੱਝਦਾ ਹੈ। ਇੱਥੋਂ ਦੀਆਂ ਬਹੁਮੰਜ਼ਲੀ ਇਮਾਰਤਾਂ, ਮਿਊਜ਼ੀਅਮ ਅਤੇ ਰੇਤ ਦੇ ਉੱਚੇ-ਉੱਚੇ ਟਿੱਬੇ ਇਸ ਨੂੰ ਖੂਬਸੂਰਤ ਦਿੱਖ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਨ। ਇੱਥੇ ਬਣੀ ਦੁਨੀਆ ਦੀ ਸਭ ਤੋਂ ਵਿਲੱਖਣ ਇਮਾਰਤ ਬੁਰਜ ਖਲੀਫਾ ਸਭ ਦਾ ਧਿਆਨ ਖਿੱਚਦੀ ਹੈ। ਇਸ ਅਜੂਬੇ ਨੂੰ ਵੇਖਣ ਲਈ ਮੈਂ ਵੀ ਬੜਾ ਉਤਾਵਲਾ ਸੀ। ਜਦੋਂ ਮੈਂ ਇਸ ਇਮਾਰਤ ਨੂੰ ਪਹਿਲੀ ਵਾਰ ਵੇਖਿਆ ਤਾਂ ਵੇਖਦਾ ਹੀ ਰਹਿ ਗਿਆ। ਹਜ਼ਾਰਾਂ ਲੋਕ ਇਹ ਨਜ਼ਾਰਾ ਸਾਹ ਰੋਕ ਕੇ ਵੇਖ ਰਹੇ ਸਨ। ਇਹ ਅਸਮਾਨ ਵਿੱਚ ਮੁੱਖ ਵਿਚਾਰ (Key Concept) ਆਧੁਨਿਕ ਤਕਨੀਕ ਦੀਆਂ ਨਵੀਆਂ ਪ੍ਰਾਪਤੀਆਂ ਤੋਂ ਜਾਣੂ ਕਰਾਉਂਦਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
  ('6216365c-4600-48be-8d32-7aa4375ffadf', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੈਂ ਕਦੇ ਸੋਚਿਆ ਵੀ ਨਹੀਂ ਸੀ ਕਿ ਇੱਕ ਈਮੇਲ ਮੇਰੀ ਜ਼ਿੰਦਗੀ ਦਾ ਸਭ ਤੋਂ ਸੁਖਦ ਅਨੁਭਵ ਬਣ ਜਾਵੇਗੀ। "ਵਧਾਈ ਹੋਵੇ! ਯੂਨੀਵਰਸਲ ਸਟੇਸ਼ਨਰਜ਼ ਨੇ ਆਪਣੀ BE ਸਾਲਾ ਵਰੇਗੰਢ ਪੂਰੀ ਕਰਨ ਦੀ ਖੁਸ਼ੀ ਵਿੱਚ ਤੁਹਾਨੂੰ ਦੁਬਈ ਦੀ ਮੁਫਤ ਯਾਤਰਾ ਲਈ ਚੁਣਿਆ ਹੈ!" ਇਹ ਪੜ੍ਹ ਕੇ ਮੇਰੇ ਦਿਲ ਦੀ ਧੜਕਣ ਤੇਜ਼ ਹੋ ਗਈ। ਮੈਂ ਮਾਂ ਨੂੰ ਜਦ ਇਹ ਗੱਲ ਦੱਸੀ ਤਾਂ ਉਹਨਾਂ ਨੇ ਕਿਹਾ ਕਿ ਕੋਈ ਮਜ਼ਾਕ ਕਰਦਾ ਹੋਵੇਗਾ। ਜਦ ਕੰਪਨੀ ਦੇ ਨਿੱਜੀ ਨੰਬਰ ਤੋਂ ਫੋਨ ਆਇਆ ਤਾਂ ਇਹ ਸੱਚ ਸਾਡੇ ਸਾਹਮਣੇ ਆਇਆ। ਮੁਫਤ ਟਿਕਟ, ਹੋਟਲ, ਆਵਾਜਾਈ ਦੀ ਸਹੂਲਤ ਸਭ ਕੁਝ ਉਹਨਾਂ ਵੱਲੋਂ ਸੀ। ਭਾਵੇਂ ਮੈਂ ਤਾਂ ਅਜੇ ਪੰਜਾਬ ਤੋਂ ਬਾਹਰ ਨਹੀਂ ਗਿਆ ਸੀ ਪਰ ਦੁਬਈ ਜਾ ਕੇ ਘੁੰਮਣ ਦਾ ਮੇਰਾ ਸੁਫਨਾ ਹਕੀਕਤ ਵਿੱਚ ਬਦਲਣ ਵਾਲਾ ਸੀ। ਇਸ ਅਚਾਨਕ ਆਈ ਖੁਸ਼ੀ ਨੂੰ ਮਹਿਸੂਸ ਕਰਦਿਆਂ ਮੇਰੇ ਤਾਂ ਪੈਰ ਹੀ ਜ਼ਮੀਨ ਉੱਤੇ ਨਹੀਂ ਲੱਗ ਰਹੇ ਸਨ। ਮੈਂ ਮੰਮੀ-ਪਾਪਾ ਨਾਲ ਮਿਲ ਕੇ ਯਾਤਰਾ ਦੀ ਹਰ ਤਰ੍ਹਾਂ ਦੀ ਤਿਆਰੀ ਕਰ ਲਈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
  ('248d5dd6-959b-460c-8064-aecca25caf87', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਿਰਧਾਰਤ ਸਮੇਂ ਉੱਤੇ ਅਸੀਂ ਦੁਬਈ ਇੰਟਰਨੈਸ਼ਨਲ ਏਅਰਪੋਰਟ ਉੱਤੇ ਉੱਤਰੇ। ਸਾਫ-ਸਫਾਈ, ਚਕਾਚੌਂਧ ਕਰਦੀਆਂ ਲਾਈਟਾਂ ਅਤੇ ਸੁਚਾਰੂ ਪ੍ਰਬੰਧਾਂ ਨੇ ਮੇਰੇ ਮਨ ਉੱਤੇ ਅਮਿੱਟ ਛਾਪ ਛੱਡੀ। ਰੇਤਲਾ ਇਲਾਕਾ ਹੋਣ ਦੇ ਬਾਵਜੂਦ ਦੁਬਈ ਨੂੰ ਸੈਲਾਨੀਆਂ ਲਈ ਖਿੱਚ ਦਾ ਕੇਂਦਰ ਬਣਾਉਣ ਦਾ ਸਿਹਰਾ ਸਮੇਂ-ਸਮੇਂ ਉੱਤੇ ਇਸ ਦੇਸ਼ ਨੂੰ ਚਲਾਉਣ ਵਾਲਿਆਂ ਦੇ ਸਿਰ ਬੱਝਦਾ ਹੈ। ਇੱਥੋਂ ਦੀਆਂ ਬਹੁਮੰਜ਼ਲੀ ਇਮਾਰਤਾਂ, ਮਿਊਜ਼ੀਅਮ ਅਤੇ ਰੇਤ ਦੇ ਉੱਚੇ-ਉੱਚੇ ਟਿੱਬੇ ਇਸ ਨੂੰ ਖੂਬਸੂਰਤ ਦਿੱਖ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਨ। ਇੱਥੇ ਬਣੀ ਦੁਨੀਆ ਦੀ ਸਭ ਤੋਂ ਵਿਲੱਖਣ ਇਮਾਰਤ ਬੁਰਜ ਖਲੀਫਾ ਸਭ ਦਾ ਧਿਆਨ ਖਿੱਚਦੀ ਹੈ। ਇਸ ਅਜੂਬੇ ਨੂੰ ਵੇਖਣ ਲਈ ਮੈਂ ਵੀ ਬੜਾ ਉਤਾਵਲਾ ਸੀ। ਜਦੋਂ ਮੈਂ ਇਸ ਇਮਾਰਤ ਨੂੰ ਪਹਿਲੀ ਵਾਰ ਵੇਖਿਆ ਤਾਂ ਵੇਖਦਾ ਹੀ ਰਹਿ ਗਿਆ। ਹਜ਼ਾਰਾਂ ਲੋਕ ਇਹ ਨਜ਼ਾਰਾ ਸਾਹ ਰੋਕ ਕੇ ਵੇਖ ਰਹੇ ਸਨ। ਇਹ ਅਸਮਾਨ ਵਿੱਚ ਮੁੱਖ ਵਿਚਾਰ (Key Concept) ਆਧੁਨਿਕ ਤਕਨੀਕ ਦੀਆਂ ਨਵੀਆਂ ਪ੍ਰਾਪਤੀਆਂ ਤੋਂ ਜਾਣੂ ਕਰਾਉਂਦਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
  ('b8014040-9b8c-4085-ad17-8db6a620ce51', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਧੀ ਖੜ੍ਹੀ ਹੋਈ ਜਾਦੂਈ ਮੂਰਤ ਵਾਂਗ ਜਾਪਦੀ ਹੈ। HBH ਮੀਟਰ ਉੱਚੀ ਇਹ ਇਮਾਰਤ ਮਨੁੱਖੀ ਕਲਪਨਾ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ ਕਲਾ ਦਾ ਅਦਭੁਤ ਨਮੂਨਾ ਹੈ। ਬੁਰਜ ਖਲੀਫਾ ਦਾ ਨਿਰਮਾਣ B@@D ਵਿੱਚ ਸ਼ੁਰੂ ਹੋਇਆ ਸੀ ਤੇ ਇਹ B@A@ ਵਿੱਚ ਪੂਰੀ ਤਰ੍ਹਾਂ ਤਿਆਰ ਹੋ ਗਈ। ਇਸ ਇਮਾਰਤ ਨੇ ਸੰਸਾਰ ਦੀ ਸਭ ਤੋਂ ਉੱਚੀ ਇਮਾਰਤ ਬਣਨ ਦਾ ਰਿਕਾਰਡ ਦਰਜ ਕਰਵਾਇਆ ਹੈ। ਇਸ ਇਮਾਰਤ ਦੀਆਂ AFC ਮੁੱਖ ਮੰਜ਼ਿਲਾਂ ਹਨ ਪਰ ਕੁੱਲ ਮਿਲਾ ਕੇ ਇਹ ਲਗਭਗ B@@ ਤਲਾਂ ਉੱਤੇ ਫੈਲੀ ਹੋਈ ਹੈ। ਇਹ ਪ੍ਰਾਜੈਕਟ ਸੰਯੁਕਤ ਅਰਬ ਅਮੀਰਾਤ ਦੀ ਇੱਕ ਪ੍ਰਸਿੱਧ ਰੀਅਲ ਅਸਟੇਟ ਕੰਪਨੀ ਐਮਾਰ ਪ੍ਰਾਪਰਟੀਜ਼ ਵੱਲੋਂ ਆਰੰਭ ਕੀਤਾ ਗਿਆ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0df1c605-5989-4ea0-bf4a-15a50f50f281', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਇਮਾਰਤ ਦਾ ਨਮੂਨਾ ਸਕਿਡਮੋਰ, ਓਵਿੰਗਸ ਐਂਡ ਮੈਰਿਲ (Skidmore, Owings & Merrill) (SOM) ਨਾਮਕ ਅਮਰੀਕੀ ਆਰਕੀਟੈਕਚਰ ਕੰਪਨੀ ਨੇ ਤਿਆਰ ਕੀਤਾ। ਮੁੱਖ ਆਰਕੀਟੈਕਟ ਐਡਰਿਅਨ ਸਮਿੱਥ ਸੀ ਜਿਸ ਨੇ ਲਿੱਲੀ ਫੁੱਲ (Hymenocallis) ਦੀ ਬਣਤਰ ਤੋਂ ਪ੍ਰੇਰਿਤ ਹੋ ਕੇ ਇਹ ਅਸਾਧਾਰਨ ਡਿਜ਼ਾਈਨ ਤਿਆਰ ਕੀਤਾ। ਇਸ ਦੀ ਬਣਤਰ ਤਕਨੀਕੀ ਅਨੋਖੇਪਨ ਨਾਲ ਭਰੀ ਹੋਈ ਹੈ। ਇਸ ਦਾ ਆਧਾਰ ਤਿਕੋਣੀ ਆਕਾਰ ਦਾ ਹੈ ਜੋ ਇੱਕ ਕੇਂਦਰੀ ਕੋਰ ਵਿੱਚੋਂ ਤਿੰਨ ਦਿਸ਼ਾਵਾਂ ਵਿੱਚ ਫੈਲਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f3a9ba19-4438-4789-8d03-8970905966bc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਨਕਸ਼ਾ ਨਾ ਸਿਰਫ਼ ਸੁੰਦਰਤਾ ਵਿੱਚ ਵਾਧਾ ਕਰਦਾ ਹੈ, ਸਗੋਂ ਇਸੇ ਤਿਕੋਣੇ ਨਮੂਨੇ ਕਰਕੇ ਹੀ ਇਹ EE ਤੋਂ F@ ਕਿਲੋਮੀਟਰ ਤੇਜ਼ ਹਵਾਵਾਂ ਦੇ ਜ਼ੋਰਦਾਰ ਝਟਕਿਆਂ ਨੂੰ ਵੀ ਆਸਾਨੀ ਨਾਲ ਸਹਿਣ ਕਰ ਲੈਂਦੀ ਹੈ। ਇਸ ਉੱਚਾਈ ਉੱਤੇ ਹਵਾ ਦਾ ਜ਼ੋਰ ਜ਼ਿਆਦਾ ਹੋਣ ਕਰਕੇ ਇਹ ਆਮ ਗੱਲ ਨਹੀਂ ਹੈ। ਇਸ ਦਾ ਵਿਸ਼ੇਸ਼ ਨਮੂਨਾ ਹਵਾ ਦੇ ਪ੍ਰਵਾਹ ਨੂੰ ਇਸ ਤਰ੍ਹਾਂ ਮੋੜਦਾ ਹੈ ਕਿ ਇਮਾਰਤ ਥਰਥਰਾਉਣ ਤੋਂ ਬਚ ਕੇ ਸ਼ਾਂਤ ਖੜ੍ਹੀ ਰਹਿੰਦੀ ਹੈ। ਇਸੇ ਡਿਜ਼ਾਈਨ ਇਸ ਦੀ ਸਥਿਰਤਾ ਦੀ ਬੁਨਿਆਦ ਬਣਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e8f375d8-063b-4c80-be84-5f491c744fe0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਦੇ ਬਾਹਰੀ ਹਿੱਸਿਆਂ ਉੱਤੇ ਲਗਾਏ ਗਏ ਵਿਸ਼ੇਸ਼ ਗਲਾਸ ਪੈਨਲਾਂ ਨੂੰ ਐਨੀ ਅਗਾਹਵਧੂ ਤਕਨੀਕ ਨਾਲ ਤਿਆਰ ਕੀਤਾ ਗਿਆ ਹੈ ਕਿ ਇਹ ਸੂਰਜ ਦੀ ਉਤਪੰਨ ਕੀਤੀ ਗਰਮੀ ਨੂੰ ਘਟਾਉਂਦੇ ਹਨ ਜਿਸ ਨਾਲ ਇਮਾਰਤ ਦੇ ਅੰਦਰ ਸ਼ੀਤਲਤਾ ਬਣੀ ਰਹਿੰਦੀ ਹੈ। ਟਿਕਾਊ ਬਣਤਰ ਅਤੇ ਕਾਫ਼ੀ ਘੱਟ ਊਰਜਾ ਖਪਤ ਕਰਨ ਵਾਲੀ ਇਹ ਸੰਰਚਨਾ ਭਵਿੱਖ ਦੀਆਂ ਇਮਾਰਤਾਂ ਲਈ ਪ੍ਰੇਰਨਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('88ce9a3d-c32e-4d5d-886f-36c6ce352e2c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬੁਰਜ ਖਲੀਫਾ ਸਿਰਫ਼ ਬਹੁਮੰਜ਼ਲੀ ਇਮਾਰਤ ਨਹੀਂ, ਸਗੋਂ ਜ਼ਿੰਦਗੀ ਜਿਊਣ ਵਾਲੀ ਥਾਂ ਹੈ। ਇੱਥੇ ਰਿਹਾਇਸ਼ੀ ਅਪਾਰਟਮੈਂਟ, ਦਫ਼ਤਰ, ਹੋਟਲ ਅਤੇ ਵਪਾਰਕ ਸਥਾਨ ਵੀ ਹਨ। ਇਮਾਰਤ ਦੇ ਨੀਵੇਂ ਤਲਾਂ ਉੱਤੇ ਅਰਮਾਨੀ ਹੋਟਲ ਦੁਬਈ ਸਥਿਤ ਹੈ ਜੋ ਇਟਲੀ ਦੇ ਮਸ਼ਹੂਰ ਡਿਜ਼ਾਈਨਰ ਜਾਰਜੀਓ ਅਰਮਾਨੀ ਦੇ ਨਾਂ ਉੱਤੇ ਬਣਾਇਆ ਗਿਆ ਇੱਕ ਵਿਲੱਖਣ ਹੋਟਲ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('02056aa6-a453-47b6-9703-b06fb795e8d5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਧੀ ਖੜ੍ਹੀ ਹੋਈ ਜਾਦੂਈ ਮੂਰਤ ਵਾਂਗ ਜਾਪਦੀ ਹੈ। HBH ਮੀਟਰ ਉੱਚੀ ਇਹ ਇਮਾਰਤ ਮਨੁੱਖੀ ਕਲਪਨਾ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ ਕਲਾ ਦਾ ਅਦਭੁਤ ਨਮੂਨਾ ਹੈ। ਬੁਰਜ ਖਲੀਫਾ ਦਾ ਨਿਰਮਾਣ B@@D ਵਿੱਚ ਸ਼ੁਰੂ ਹੋਇਆ ਸੀ ਤੇ ਇਹ B@A@ ਵਿੱਚ ਪੂਰੀ ਤਰ੍ਹਾਂ ਤਿਆਰ ਹੋ ਗਈ। ਇਸ ਇਮਾਰਤ ਨੇ ਸੰਸਾਰ ਦੀ ਸਭ ਤੋਂ ਉੱਚੀ ਇਮਾਰਤ ਬਣਨ ਦਾ ਰਿਕਾਰਡ ਦਰਜ ਕਰਵਾਇਆ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('226b3e11-c630-422f-bf3c-eb7575d60b2f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਇਮਾਰਤ ਦੀਆਂ AFC ਮੁੱਖ ਮੰਜ਼ਿਲਾਂ ਹਨ ਪਰ ਕੁੱਲ ਮਿਲਾ ਕੇ ਇਹ ਲਗਭਗ B@@ ਤਲਾਂ ਉੱਤੇ ਫੈਲੀ ਹੋਈ ਹੈ। ਇਹ ਪ੍ਰਾਜੈਕਟ ਸੰਯੁਕਤ ਅਰਬ ਅਮੀਰਾਤ ਦੀ ਇੱਕ ਪ੍ਰਸਿੱਧ ਰੀਅਲ ਅਸਟੇਟ ਕੰਪਨੀ ਐਮਾਰ ਪ੍ਰਾਪਰਟੀਜ਼ ਵੱਲੋਂ ਆਰੰਭ ਕੀਤਾ ਗਿਆ ਸੀ। ਇਸ ਇਮਾਰਤ ਦਾ ਨਮੂਨਾ ਸਕਿਡਮੋਰ, ਓਵਿੰਗਸ ਐਂਡ ਮੈਰਿਲ (Skidmore, Owings & Merrill) (SOM) ਨਾਮਕ ਅਮਰੀਕੀ ਆਰਕੀਟੈਕਚਰ ਕੰਪਨੀ ਨੇ ਤਿਆਰ ਕੀਤਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8bfdd1e8-5177-407c-a7b8-e9bf22e6e556', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੁੱਖ ਆਰਕੀਟੈਕਟ ਐਡਰਿਅਨ ਸਮਿੱਥ ਸੀ ਜਿਸ ਨੇ ਲਿੱਲੀ ਫੁੱਲ (Hymenocallis) ਦੀ ਬਣਤਰ ਤੋਂ ਪ੍ਰੇਰਿਤ ਹੋ ਕੇ ਇਹ ਅਸਾਧਾਰਨ ਡਿਜ਼ਾਈਨ ਤਿਆਰ ਕੀਤਾ। ਇਸ ਦੀ ਬਣਤਰ ਤਕਨੀਕੀ ਅਨੋਖੇਪਨ ਨਾਲ ਭਰੀ ਹੋਈ ਹੈ। ਇਸ ਦਾ ਆਧਾਰ ਤਿਕੋਣੀ ਆਕਾਰ ਦਾ ਹੈ ਜੋ ਇੱਕ ਕੇਂਦਰੀ ਕੋਰ ਵਿੱਚੋਂ ਤਿੰਨ ਦਿਸ਼ਾਵਾਂ ਵਿੱਚ ਫੈਲਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('bd201354-2e83-4658-9c8f-9557a65d2b4d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਹ ਨਕਸ਼ਾ ਨਾ ਸਿਰਫ਼ ਸੁੰਦਰਤਾ ਵਿੱਚ ਵਾਧਾ ਕਰਦਾ ਹੈ, ਸਗੋਂ ਇਸੇ ਤਿਕੋਣੇ ਨਮੂਨੇ ਕਰਕੇ ਹੀ ਇਹ EE ਤੋਂ F@ ਕਿਲੋਮੀਟਰ ਤੇਜ਼ ਹਵਾਵਾਂ ਦੇ ਜ਼ੋਰਦਾਰ ਝਟਕਿਆਂ ਨੂੰ ਵੀ ਆਸਾਨੀ ਨਾਲ ਸਹਿਣ ਕਰ ਲੈਂਦੀ ਹੈ। ਇਸ ਉੱਚਾਈ ਉੱਤੇ ਹਵਾ ਦਾ ਜ਼ੋਰ ਜ਼ਿਆਦਾ ਹੋਣ ਕਰਕੇ ਇਹ ਆਮ ਗੱਲ ਨਹੀਂ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('67a5e0a9-6a2a-4edb-b5c7-b4edd04cb746', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਦਾ ਵਿਸ਼ੇਸ਼ ਨਮੂਨਾ ਹਵਾ ਦੇ ਪ੍ਰਵਾਹ ਨੂੰ ਇਸ ਤਰ੍ਹਾਂ ਮੋੜਦਾ ਹੈ ਕਿ ਇਮਾਰਤ ਥਰਥਰਾਉਣ ਤੋਂ ਬਚ ਕੇ ਸ਼ਾਂਤ ਖੜ੍ਹੀ ਰਹਿੰਦੀ ਹੈ। ਇਸੇ ਡਿਜ਼ਾਈਨ ਇਸ ਦੀ ਸਥਿਰਤਾ ਦੀ ਬੁਨਿਆਦ ਬਣਦਾ ਹੈ। ਇਸ ਦੇ ਬਾਹਰੀ ਹਿੱਸਿਆਂ ਉੱਤੇ ਲਗਾਏ ਗਏ ਵਿਸ਼ੇਸ਼ ਗਲਾਸ ਪੈਨਲਾਂ ਨੂੰ ਐਨੀ ਅਗਾਹਵਧੂ ਤਕਨੀਕ ਨਾਲ ਤਿਆਰ ਕੀਤਾ ਗਿਆ ਹੈ ਕਿ ਇਹ ਸੂਰਜ ਦੀ ਉਤਪੰਨ ਕੀਤੀ ਗਰਮੀ ਨੂੰ ਘਟਾਉਂਦੇ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
