  ('61c3d4a4-2683-4072-8338-6caf3e8e4955', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੱਥੇ ਰਿਹਾਇਸ਼ੀ ਅਪਾਰਟਮੈਂਟ, ਦਫ਼ਤਰ, ਹੋਟਲ ਅਤੇ ਵਪਾਰਕ ਸਥਾਨ ਵੀ ਹਨ। ਇਮਾਰਤ ਦੇ ਨੀਵੇਂ ਤਲਾਂ ਉੱਤੇ ਅਰਮਾਨੀ ਹੋਟਲ ਦੁਬਈ ਸਥਿਤ ਹੈ ਜੋ ਇਟਲੀ ਦੇ ਮਸ਼ਹੂਰ ਡਿਜ਼ਾਈਨਰ ਜਾਰਜੀਓ ਅਰਮਾਨੀ ਦੇ ਨਾਂ ਉੱਤੇ ਬਣਾਇਆ ਗਿਆ ਇੱਕ ਵਿਲੱਖਣ ਹੋਟਲ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('705d66c6-4295-4d79-9a0d-f9f262a7d8b7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਧੀ ਖੜ੍ਹੀ ਹੋਈ ਜਾਦੂਈ ਮੂਰਤ ਵਾਂਗ ਜਾਪਦੀ ਹੈ। HBH ਮੀਟਰ ਉੱਚੀ ਇਹ ਇਮਾਰਤ ਮਨੁੱਖੀ ਕਲਪਨਾ ਅਤੇ ਇੰਜੀਨੀਅਰਿੰਗ ਕਲਾ ਦਾ ਅਦਭੁਤ ਨਮੂਨਾ ਹੈ। ਬੁਰਜ ਖਲੀਫਾ ਦਾ ਨਿਰਮਾਣ B@@D ਵਿੱਚ ਸ਼ੁਰੂ ਹੋਇਆ ਸੀ ਤੇ ਇਹ B@A@ ਵਿੱਚ ਪੂਰੀ ਤਰ੍ਹਾਂ ਤਿਆਰ ਹੋ ਗਈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a46e16f0-76e0-4cd8-8d77-d267aa8389c9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਇਮਾਰਤ ਨੇ ਸੰਸਾਰ ਦੀ ਸਭ ਤੋਂ ਉੱਚੀ ਇਮਾਰਤ ਬਣਨ ਦਾ ਰਿਕਾਰਡ ਦਰਜ ਕਰਵਾਇਆ ਹੈ। ਇਸ ਇਮਾਰਤ ਦੀਆਂ AFC ਮੁੱਖ ਮੰਜ਼ਿਲਾਂ ਹਨ ਪਰ ਕੁੱਲ ਮਿਲਾ ਕੇ ਇਹ ਲਗਭਗ B@@ ਤਲਾਂ ਉੱਤੇ ਫੈਲੀ ਹੋਈ ਹੈ। ਇਹ ਪ੍ਰਾਜੈਕਟ ਸੰਯੁਕਤ ਅਰਬ ਅਮੀਰਾਤ ਦੀ ਇੱਕ ਪ੍ਰਸਿੱਧ ਰੀਅਲ ਅਸਟੇਟ ਕੰਪਨੀ ਐਮਾਰ ਪ੍ਰਾਪਰਟੀਜ਼ ਵੱਲੋਂ ਆਰੰਭ ਕੀਤਾ ਗਿਆ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('23188493-bc86-4546-aebe-cbff731068f6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਇਮਾਰਤ ਦਾ ਨਮੂਨਾ ਸਕਿਡਮੋਰ, ਓਵਿੰਗਸ ਐਂਡ ਮੈਰਿਲ (Skidmore, Owings & Merrill) (SOM) ਨਾਮਕ ਅਮਰੀਕੀ ਆਰਕੀਟੈਕਚਰ ਕੰਪਨੀ ਨੇ ਤਿਆਰ ਕੀਤਾ। ਮੁੱਖ ਆਰਕੀਟੈਕਟ ਐਡਰਿਅਨ ਸਮਿੱਥ ਸੀ ਜਿਸ ਨੇ ਲਿੱਲੀ ਫੁੱਲ (Hymenocallis) ਦੀ ਬਣਤਰ ਤੋਂ ਪ੍ਰੇਰਿਤ ਹੋ ਕੇ ਇਹ ਅਸਾਧਾਰਨ ਡਿਜ਼ਾਈਨ ਤਿਆਰ ਕੀਤਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('769e04b0-3cd7-4436-bb01-bd477bd906c5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਦੀ ਬਣਤਰ ਤਕਨੀਕੀ ਅਨੋਖੇਪਨ ਨਾਲ ਭਰੀ ਹੋਈ ਹੈ। ਇਸ ਦਾ ਆਧਾਰ ਤਿਕੋਣੀ ਆਕਾਰ ਦਾ ਹੈ ਜੋ ਇੱਕ ਕੇਂਦਰੀ ਕੋਰ ਵਿੱਚੋਂ ਤਿੰਨ ਦਿਸ਼ਾਵਾਂ ਵਿੱਚ ਫੈਲਦਾ ਹੈ। ਇਹ ਨਕਸ਼ਾ ਨਾ ਸਿਰਫ਼ ਸੁੰਦਰਤਾ ਵਿੱਚ ਵਾਧਾ ਕਰਦਾ ਹੈ, ਸਗੋਂ ਇਸੇ ਤਿਕੋਣੇ ਨਮੂਨੇ ਕਰਕੇ ਹੀ ਇਹ EE ਤੋਂ F@ ਕਿਲੋਮੀਟਰ ਤੇਜ਼ ਹਵਾਵਾਂ ਦੇ ਜ਼ੋਰਦਾਰ ਝਟਕਿਆਂ ਨੂੰ ਵੀ ਆਸਾਨੀ ਨਾਲ ਸਹਿਣ ਕਰ ਲੈਂਦੀ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7a48c92e-8fa7-4dc2-9d2c-949c551e5b7d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਉੱਚਾਈ ਉੱਤੇ ਹਵਾ ਦਾ ਜ਼ੋਰ ਜ਼ਿਆਦਾ ਹੋਣ ਕਰਕੇ ਇਹ ਆਮ ਗੱਲ ਨਹੀਂ ਹੈ। ਇਸ ਦਾ ਵਿਸ਼ੇਸ਼ ਨਮੂਨਾ ਹਵਾ ਦੇ ਪ੍ਰਵਾਹ ਨੂੰ ਇਸ ਤਰ੍ਹਾਂ ਮੋੜਦਾ ਹੈ ਕਿ ਇਮਾਰਤ ਥਰਥਰਾਉਣ ਤੋਂ ਬਚ ਕੇ ਸ਼ਾਂਤ ਖੜ੍ਹੀ ਰਹਿੰਦੀ ਹੈ। ਇਸੇ ਡਿਜ਼ਾਈਨ ਇਸ ਦੀ ਸਥਿਰਤਾ ਦੀ ਬੁਨਿਆਦ ਬਣਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('de1af19c-f1f8-4d6c-8b72-5e211a01b965', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਦੇ ਬਾਹਰੀ ਹਿੱਸਿਆਂ ਉੱਤੇ ਲਗਾਏ ਗਏ ਵਿਸ਼ੇਸ਼ ਗਲਾਸ ਪੈਨਲਾਂ ਨੂੰ ਐਨੀ ਅਗਾਹਵਧੂ ਤਕਨੀਕ ਨਾਲ ਤਿਆਰ ਕੀਤਾ ਗਿਆ ਹੈ ਕਿ ਇਹ ਸੂਰਜ ਦੀ ਉਤਪੰਨ ਕੀਤੀ ਗਰਮੀ ਨੂੰ ਘਟਾਉਂਦੇ ਹਨ ਜਿਸ ਨਾਲ ਇਮਾਰਤ ਦੇ ਅੰਦਰ ਸ਼ੀਤਲਤਾ ਬਣੀ ਰਹਿੰਦੀ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
