  ('f201bb35-e692-4157-8482-fa0a927f5a5a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਇਮਾਰਤ ਦੀਆਂ AFC ਮੁੱਖ ਮੰਜ਼ਿਲਾਂ ਹਨ ਪਰ ਕੁੱਲ ਮਿਲਾ ਕੇ ਇਹ ਲਗਭਗ B@@ ਤਲਾਂ ਉੱਤੇ ਫੈਲੀ ਹੋਈ ਹੈ। ਇਹ ਪ੍ਰਾਜੈਕਟ ਸੰਯੁਕਤ ਅਰਬ ਅਮੀਰਾਤ ਦੀ ਇੱਕ ਪ੍ਰਸਿੱਧ ਰੀਅਲ ਅਸਟੇਟ ਕੰਪਨੀ ਐਮਾਰ ਪ੍ਰਾਪਰਟੀਜ਼ ਵੱਲੋਂ ਆਰੰਭ ਕੀਤਾ ਗਿਆ ਸੀ। ਇਸ ਇਮਾਰਤ ਦਾ ਨਮੂਨਾ ਸਕਿਡਮੋਰ, ਓਵਿੰਗਸ ਐਂਡ ਮੈਰਿਲ (Skidmore, Owings & Merrill) (SOM) ਨਾਮਕ ਅਮਰੀਕੀ ਆਰਕੀਟੈਕਚਰ ਕੰਪਨੀ ਨੇ ਤਿਆਰ ਕੀਤਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f0fb4c63-6cf7-4330-bb7c-fefbe8cac689', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੁੱਖ ਆਰਕੀਟੈਕਟ ਐਡਰਿਅਨ ਸਮਿੱਥ ਸੀ ਜਿਸ ਨੇ ਲਿੱਲੀ ਫੁੱਲ (Hymenocallis) ਦੀ ਬਣਤਰ ਤੋਂ ਪ੍ਰੇਰਿਤ ਹੋ ਕੇ ਇਹ ਅਸਾਧਾਰਨ ਡਿਜ਼ਾਈਨ ਤਿਆਰ ਕੀਤਾ। ਇਸ ਦੀ ਬਣਤਰ ਤਕਨੀਕੀ ਅਨੋਖੇਪਨ ਨਾਲ ਭਰੀ ਹੋਈ ਹੈ। ਇਸ ਦਾ ਆਧਾਰ ਤਿਕੋਣੀ ਆਕਾਰ ਦਾ ਹੈ ਜੋ ਇੱਕ ਕੇਂਦਰੀ ਕੋਰ ਵਿੱਚੋਂ ਤਿੰਨ ਦਿਸ਼ਾਵਾਂ ਵਿੱਚ ਫੈਲਦਾ ਹੈ। ਇਹ ਨਕਸ਼ਾ ਨਾ ਸਿਰਫ਼ ਸੁੰਦਰਤਾ ਵਿੱਚ ਵਾਧਾ ਕਰਦਾ ਹੈ, ਸਗੋਂ ਇਸੇ ਤਿਕੋਣੇ ਨਮੂਨੇ ਕਰਕੇ ਹੀ ਇਹ EE ਤੋਂ F@ ਕਿਲੋਮੀਟਰ ਤੇਜ਼ ਹਵਾਵਾਂ ਦੇ ਜ਼ੋਰਦਾਰ ਝਟਕਿਆਂ ਨੂੰ ਵੀ ਆਸਾਨੀ ਨਾਲ ਸਹਿਣ ਕਰ ਲੈਂਦੀ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a1717e55-a6af-4c35-97cc-b9509b8c56f3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਉੱਚਾਈ ਉੱਤੇ ਹਵਾ ਦਾ ਜ਼ੋਰ ਜ਼ਿਆਦਾ ਹੋਣ ਕਰਕੇ ਇਹ ਆਮ ਗੱਲ ਨਹੀਂ ਹੈ। ਇਸ ਦਾ ਵਿਸ਼ੇਸ਼ ਨਮੂਨਾ ਹਵਾ ਦੇ ਪ੍ਰਵਾਹ ਨੂੰ ਇਸ ਤਰ੍ਹਾਂ ਮੋੜਦਾ ਹੈ ਕਿ ਇਮਾਰਤ ਥਰਥਰਾਉਣ ਤੋਂ ਬਚ ਕੇ ਸ਼ਾਂਤ ਖੜ੍ਹੀ ਰਹਿੰਦੀ ਹੈ। ਇਸੇ ਡਿਜ਼ਾਈਨ ਇਸ ਦੀ ਸਥਿਰਤਾ ਦੀ ਬੁਨਿਆਦ ਬਣਦਾ ਹੈ। ਇਸ ਦੇ ਬਾਹਰੀ ਹਿੱਸਿਆਂ ਉੱਤੇ ਲਗਾਏ ਗਏ ਵਿਸ਼ੇਸ਼ ਗਲਾਸ ਪੈਨਲਾਂ ਨੂੰ ਐਨੀ ਅਗਾਹਵਧੂ ਤਕਨੀਕ ਨਾਲ ਤਿਆਰ ਕੀਤਾ ਗਿਆ ਹੈ ਕਿ ਇਹ ਸੂਰਜ ਦੀ ਉਤਪੰਨ ਕੀਤੀ ਗਰਮੀ ਨੂੰ ਘਟਾਉਂਦੇ ਹਨ ਜਿਸ ਨਾਲ ਇਮਾਰਤ ਦੇ ਅੰਦਰ ਸ਼ੀਤਲਤਾ ਬਣੀ ਰਹਿੰਦੀ ਹੈ। ਟਿਕਾਊ ਬਣਤਰ ਅਤੇ ਕਾਫ਼ੀ ਘੱਟ ਊਰਜਾ ਖਪਤ ਕਰਨ ਵਾਲੀ ਇਹ ਸੰਰਚਨਾ ਭਵਿੱਖ ਦੀਆਂ ਇਮਾਰਤਾਂ ਲਈ ਪ੍ਰੇਰਨਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL);
