  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲੇਖਕ ਨੂੰ ਦੁਬਈ ਯਾਤਰਾ ਬਾਰੇ ਕਿਵੇਂ ਪਤਾ ਲੱਗਾ ਅਤੇ ਉਸਦੀ ਪਹਿਲੀ ਪ੍ਰਤੀਕਿਰਿਆ ਕੀ ਸੀ?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '449cbc4a-b3d9-49e8-85f5-d8ca941942ce', NULL, 1),
