  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੰਪਨੀ ਵੱਲੋਂ ਯਾਤਰਾ ਲਈ ਕਿਹੜੀਆਂ ਸਹੂਲਤਾਂ ਪ੍ਰਦਾਨ ਕੀਤੀਆਂ ਗਈਆਂ ਸਨ?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '449cbc4a-b3d9-49e8-85f5-d8ca941942ce', NULL, 3),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲੇਖਕ ਲਈ ਇਹ ਯਾਤਰਾ ਕਿਉਂ ਖਾਸ ਸੀ ਅਤੇ ਉਸਨੇ ਆਪਣੀ ਖੁਸ਼ੀ ਨੂੰ ਕਿਵੇਂ ਪ੍ਰਗਟ ਕੀਤਾ?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '449cbc4a-b3d9-49e8-85f5-d8ca941942ce', NULL, 4),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲੇਖਕ ਨੇ ਯਾਤਰਾ ਦੀ ਤਿਆਰੀ ਵਿੱਚ ਕਿਸਦੀ ਮਦਦ ਲਈ?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '449cbc4a-b3d9-49e8-85f5-d8ca941942ce', NULL, 5),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੁਬਈ ਇੰਟਰਨੈਸ਼ਨਲ ਏਅਰਪੋਰਟ 'ਤੇ ਪਹੁੰਚ ਕੇ ਲੇਖਕ ਨੂੰ ਕਿਹੜੀਆਂ ਚੀਜ਼ਾਂ ਨੇ ਪ੍ਰਭਾਵਿਤ ਕੀਤਾ?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '605c0cb0-d9e9-4108-b902-02a1ef05ae06', NULL, 1),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੁਬਈ ਇੱਕ ਰੇਤਲਾ ਇਲਾਕਾ ਹੋਣ ਦੇ ਬਾਵਜੂਦ ਸੈਲਾਨੀਆਂ ਲਈ ਖਿੱਚ ਦਾ ਕੇਂਦਰ ਕਿਵੇਂ ਬਣਿਆ?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '605c0cb0-d9e9-4108-b902-02a1ef05ae06', NULL, 2),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੁਬਈ ਦੀ ਖੂਬਸੂਰਤੀ ਵਿੱਚ ਕਿਹੜੀਆਂ ਚੀਜ਼ਾਂ ਦਾ ਯੋਗਦਾਨ ਹੈ?$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '605c0cb0-d9e9-4108-b902-02a1ef05ae06', NULL, 3),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '1d80b1be-df56-4acb-b0f8-cc966183a46b', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬੁਰਜ ਖਲੀਫਾ ਦੀ ਵਿਲੱਖਣਤਾ ਅਤੇ ਇਸਦੇ ਪ੍ਰਭਾਵ ਬਾਰੇ ਲੇਖਕ ਦੇ ਅਨੁਭਵ ਦਾ ਵਰਣਨ ਕਰੋ।$qbx$, 'short_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-56-740Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, '605c0cb0-d9e9-4108-b902-02a1ef05ae06', NULL, 4),
